debug.error_function_source:
async def act(page):
    import asyncio
    import csv
    import os
    import re

    # Small stabilization wait
    await asyncio.sleep(1)

    download_path = 'orders.csv'
    try:
        if os.path.exists(download_path):
            os.remove(download_path)
    except Exception:
        pass

    # Try direct export URL first (use async context manager correctly)
    try:
        async with page.expect_download() as download_info:
            await page.goto('/index.php/admin/sales_order/exportCsv/')
        download = await download_info.value
        await download.save_as(download_path)
    except Exception:
        # Fallback: scope to Export toolbar cell then click Export button
        try:
            cell_locator = page.get_by_role("cell", name=re.compile(r"Export to", re.I))
            if await cell_locator.count() == 0:
                cell_locator = page.get_by_role("cell", name="Export to: CSV Export")

            if await cell_locator.count() == 0:
                raise RuntimeError("Export toolbar cell not found")

            export_button = cell_locator.get_by_role("button", name="Export")
            if await export_button.count() == 0:
                raise RuntimeError("Export button not found in Export cell")

            async with page.expect_download() as download_info:
                await export_button.first.click(force=True)
            download = await download_info.value
            await download.save_as(download_path)
        except Exception as e:
            raise RuntimeError(f"Failed to trigger or capture orders CSV download: {e}")

    # Parse CSV and count cancelled orders per customer
    counts = {}
    try:
        with open(download_path, newline='', encoding='utf-8', errors='replace') as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames or []

            # Find status field
            status_field = None
            for h in headers:
                if h and 'status' in h.lower():
                    status_field = h
                    break

            # Prefer 'Bill to Name' or other combined name fields
            combined_name_field = None
            for h in headers:
                if not h:
                    continue
                low = h.lower()
                if 'bill' in low and 'name' in low:
                    combined_name_field = h
                    break
                if 'customer' in low and 'name' in low:
                    combined_name_field = h
                    break
                if low == 'name' or low in ('customer_name', 'billing_name', 'bill_to_name'):
                    combined_name_field = h
                    break

            # firstname/lastname/email fallbacks
            firstname_field = None
            lastname_field = None
            email_field = None
            for h in headers:
                if not h:
                    continue
                low = h.lower()
                if (('first' in low and 'name' in low) or low.endswith('firstname')) and firstname_field is None:
                    firstname_field = h
                if (('last' in low and 'name' in low) or low.endswith('lastname')) and lastname_field is None:
                    lastname_field = h
                if 'email' in low and email_field is None:
                    email_field = h

            for row in reader:
                # Get status value safely
                if status_field:
                    status_val = (row.get(status_field) or '')
                else:
                    status_val = ' '.join((row.get(h) or '') for h in headers)

                if 'cancel' not in status_val.lower():
                    continue

                # Build customer identifier safely
                customer = None
                if combined_name_field and (row.get(combined_name_field) or '').strip():
                    customer = (row.get(combined_name_field) or '').strip()
                else:
                    first = (row.get(firstname_field) or '').strip() if firstname_field else ''
                    last = (row.get(lastname_field) or '').strip() if lastname_field else ''
                    if first or last:
                        customer = (first + ' ' + last).strip()
                    elif email_field and (row.get(email_field) or '').strip():
                        customer = (row.get(email_field) or '').strip()
                    else:
                        # fallback: first non-empty cell
                        for h in headers:
                            v = (row.get(h) or '').strip()
                            if v:
                                customer = v
                                break
                        if not customer:
                            customer = '__unknown__'

                counts[customer] = counts.get(customer, 0) + 1
    except FileNotFoundError:
        raise RuntimeError('Downloaded CSV file not found')

    max_count = max(counts.values()) if counts else 0

    # Print and return the numeric result
    print(max_count)
    return max_count

